#include <bits/stdc++.h>
using namespace std;

using lint = long long;
constexpr lint MOD = 1000000007LL;

lint mod_pow(lint base, lint exp) {
    lint res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int n, m;
lint freq1[(1<<20)], freq2[(1<<20)];
lint probs[10][10];
int mapper1[(1<<20)], mapper2[(1<<20)];
int mapping[30];

void process_subset(int idx, vector<int>& choice, lint weight) {
    if (idx == m) {
        int bit = 0, pos = 0;
        for (int s = 0; s < (1<<n); ++s) {
            if (__builtin_popcount(s) != m) continue;
            vector<int> idxs;
            for (int i = 0; i < n; ++i) {
                if ((s >> i) & 1) idxs.push_back(i);
            }
            sort(idxs.begin(), idxs.end());
            bool found = false;
            do {
                bool ok = true;
                for (int k = 0; k < m; ++k) {
                    if (!((choice[k] >> idxs[k]) & 1)) {
                        ok = false;
                        break;
                    }
                }
                if (ok) { found = true; break; }
            } while (next_permutation(idxs.begin(), idxs.end()));
            if (found) bit |= 1 << pos;
            ++pos;
        }
        freq1[bit] = (freq1[bit] + weight) % MOD;
        return;
    }

    for (int s = 0; s < (1<<n); ++s) {
        choice.push_back(s);
        lint cur = weight;
        for (int k = 0; k < n; ++k) {
            if ((s >> k) & 1)
                cur = cur * probs[idx][k] % MOD;
            else
                cur = cur * (MOD + 1 - probs[idx][k]) % MOD;
        }
        process_subset(idx + 1, choice, cur);
        choice.pop_back();
    }
}

void process_complement(int idx, vector<int>& choice, lint weight) {
    if (idx == n) {
        int bit = 0, pos = 0;
        for (int s = 0; s < (1<<n); ++s) {
            if (__builtin_popcount(s) != n - m) continue;
            vector<int> idxs;
            for (int i = 0; i < n; ++i) {
                if ((s >> i) & 1) idxs.push_back(i);
            }
            sort(idxs.begin(), idxs.end());
            bool found = false;
            do {
                bool ok = true;
                for (int k = 0; k < n - m; ++k) {
                    if (!((choice[k] >> idxs[k]) & 1)) {
                        ok = false;
                        break;
                    }
                }
                if (ok) { found = true; break; }
            } while (next_permutation(idxs.begin(), idxs.end()));
            if (found) bit |= 1 << pos;
            ++pos;
        }
        freq2[bit] = (freq2[bit] + weight) % MOD;
        return;
    }

    for (int s = 0; s < (1<<n); ++s) {
        choice.push_back(s);
        lint cur = weight;
        for (int k = 0; k < n; ++k) {
            if ((s >> k) & 1)
                cur = cur * probs[idx][k] % MOD;
            else
                cur = cur * (MOD + 1 - probs[idx][k]) % MOD;
        }
        process_complement(idx + 1, choice, cur);
        choice.pop_back();
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int val; cin >> val;
            probs[i][j] = 1LL * val * mod_pow(100, MOD - 2) % MOD;
            if (probs[i][j] < 0) probs[i][j] += MOD;
        }
    }

    if (n == 1) {
        cout << probs[0][0] << '\n';
        return 0;
    }

    m = n / 2;
    vector<int> buffer;
    process_subset(0, buffer, 1);

    for (int i = 0; i < (1<<20); ++i) freq1[i] %= MOD;

    for (int b = 0; b < 20; ++b) {
        for (int s = 0; s < (1<<20); ++s) {
            if ((s >> b) & 1) {
                freq1[s] = (freq1[s] + freq1[s ^ (1 << b)]) % MOD;
            }
        }
    }

    lint global_sum = freq1[(1<<20) - 1];

    buffer.clear();
    process_complement(m, buffer, 1);

    for (int i = 0; i < (1<<20); ++i) freq2[i] %= MOD;

    memset(mapper1, -1, sizeof(mapper1));
    int counter = 0;
    for (int s = 0; s < (1<<n); ++s) {
        if (__builtin_popcount(s) != m) continue;
        mapper1[s] = counter++;
    }

    memset(mapper2, -1, sizeof(mapper2));
    counter = 0;
    for (int s = 0; s < (1<<n); ++s) {
        if (__builtin_popcount(s) != n - m) continue;
        mapping[counter] = mapper1[(1 << n) - 1 - s];
        mapper2[s] = counter++;
    }

    lint result = 0;
    for (int s = 0; s < (1<<counter); ++s) {
        lint val = freq2[s];
        int mask = 0;
        for (int b = 0; b < counter; ++b) {
            if ((s >> b) & 1) continue;
            mask |= 1 << mapping[b];
        }
        result = (result + val * ((global_sum - freq1[mask] + MOD) % MOD)) % MOD;
    }

    cout << result % MOD << '\n';
    return 0;
}
